#!/bin/bash
# Hardware validation of the Phase 3 filtered-write interference claim (2026-10-21/22): exact commands. Run from the repo root on c28
# (Slurm job 315259, 256 cpus). The CXL DAX devices are root 0600 since the 2026-10-18 reboot (machine-state.txt), so every
# CXL-targeted store is COUNTED but NOT ISSUED by kvreplay; the DRAM-targeted part of each stream is replayed physically.
# Streams per configuration (from the Phase 3 write logs, writelogs/, regenerated by scripts/kv_joint_sim.py --write-log, identical results):
#   admitall = split_lru (admit all, 32% hash share to DRAM), filtered = value_split (RQ1 admission, same hash share),
#   budget   = value_split's stores with the tier decided LIVE by kvreplay's token bucket (B, d of the Phase 3 selection, chosen.json).
# Neighbour: the 80-thread Adam step on cpus 0-79 (benchmarks/budget/opt_step.py 80 1500 ...), 25 s settle, 60 s quiet window, then the
# replay of the scored window; SLO metric slow_p99 = p99 step time during / quiet - 1 (<= 7%, as on 2026-10-12).
# kvreplay: 64 workers on cpus 96-127 + 224-255 (CCDs 6-7), NT stores from a cache-resident pseudo-random source, 9.5 GB/s link pacing
# per block stream, 64 GiB DRAM arena, 10 ms logging. Build: gcc -O2 -g -std=gnu11 -Wall -Wextra -mavx2 -pthread kvreplay.c -o kvreplay
set -u
cd /home/ghu4/CXL
O=experimental_results/2026-10-21-hw-validation-filtered-writes; L=$O/writelogs; R=benchmarks/memory/run_kvreplay.py
win() { python3 - "$1" <<'EOF'
import sys
f = sys.argv[1]; hdr = open(f).readline().split(); t0 = float(hdr[hdr.index("scored_wall_start") + 1]); t1 = 0.0
for l in open(f):
    if l[0] == "S":
        x = l.split()
        if x[4] == "1": t1 = max(t1, float(x[1]))
print(f"{t0:.3f} {t1 + 0.001:.3f}")
EOF
}
declare -A BUD=([conversation-8b-8x]="8 1" [conversation-70b-4x]="4 1" [toolagent-8b-8x]="32 1" [toolagent-70b-4x]="8 1" [conversation-70b-8x]="12 1")
run() {   # run <group> <tag> <cfg|none> <stream> <neighbor> [extra kvreplay options]
  local g=$1 tag=$2 cfg=$3 stream=$4 nb=$5 extra=${6:-}
  grep -q "^M done" $O/$g/$tag-meta.txt 2>/dev/null && return
  echo "$(date +%T) $g/$tag"
  if [ "$cfg" = none ]; then python3 $R $O/$g $tag none 0 0 --neighbor $nb --before-s 60 --alone-s 420; return; fi
  local log=$L/$cfg-split_lru.txt; [ "$stream" != admitall ] && log=$L/$cfg-value_split.txt
  read t0 t1 < <(win $log)
  [ "$stream" = budget ] && { set -- ${BUD[$cfg]}; extra="$extra --budget $1 --depth $2"; }
  local bef=60; [ "$nb" = none ] && bef=5
  python3 $R $O/$g $tag $log $t0 $t1 --neighbor $nb --before-s $bef --replay "$extra"
}
CFGS="conversation-8b-8x conversation-70b-4x toolagent-8b-8x toolagent-70b-4x"
run alone alone-r1 none - opt
# fidelity without a neighbour: does the replayer meet its schedule?
for c in $CFGS; do run fid fid-$c-admitall $c admitall none; done
for c in conversation-8b-8x conversation-70b-4x; do run fid fid-$c-filtered $c filtered none; done
# the co-runs (D2 admit-all, D3 filtered, D4 filtered + live budget), reps interleaved
for rep in 1 2 3; do
  for c in $CFGS; do for s in admitall filtered budget; do run corun corun-$c-$s-r$rep $c $s opt; done; done
  [ $rep = 1 ] && run alone alone-r2 none - opt
done
# controls at 70B 4x conversation: writer threads on CCD 4 (Adam's cpus 64-79), CPU-only (no memory traffic), plain stores
C=conversation-70b-4x; CCD4="--cpus 64-79,192-207 --workers 32"
for rep in 1 2; do
  run ctrl ctrl-ccd4-filtered-r$rep $C filtered opt "$CCD4"
  run ctrl ctrl-ccd4-admitall-r$rep $C admitall opt "$CCD4"
  run ctrl ctrl-ccd4-none-admitall-r$rep $C admitall opt "$CCD4 --store none"
  run ctrl ctrl-plain-filtered-r$rep $C filtered opt "--store plain"
done
run ctrl ctrl-ccd67-none-admitall-r1 $C admitall opt "--store none"
run ctrl ctrl-plain-admitall-r1 $C admitall opt "--store plain"
run alone alone-r3 none - opt
# 70B 8x conversation (the heaviest real configuration of Phase 3)
for rep in 1 2; do for s in admitall filtered budget; do run x8 x8-conversation-70b-8x-$s-r$rep conversation-70b-8x $s opt; done; done
for g in alone fid corun ctrl x8; do python3 benchmarks/memory/analyze_kvreplay.py $O/$g > $O/$g/summary.md; done
echo "ALLDONE $(date)"
